independent.solution:
import re

tracked = {"src/run.py": "import os\nkey = os.environ['DATAFORGE_API_KEY']\n", "config.env": "DATAFORGE_API_KEY=abc12345\n", "data/orders.csv": "order_id\nO1\n", "README.md": "# Demo\n"}

def audit(tracked):
    problems = []
    for path, content in tracked.items():
        if re.search(r"KEY=[A-Za-z0-9]{6,}", content):
            problems.append(path + ": secret")
        if path.endswith((".db", ".csv")):
            problems.append(path + ": data file")
    if ".gitignore" not in tracked:
        problems.append("missing .gitignore")
    return sorted(problems)

for p in audit(tracked) or ["clean"]:
    print(p)
fixed = {"src/run.py": tracked["src/run.py"], ".gitignore": ".env\n*.db\n", "README.md": "# Demo\n"}
for p in audit(fixed) or ["clean"]:
    print(p)
